from django.db import migrations, models

# Interest rates used to be entered as a percentage ("5 for 5%") but were applied
# as a factor, so a stored 5 paid 500% per week. Rates are fractions from now on.
MAX_INTEREST_RATE = 0.10


def convert_rate(rate: float) -> float:
    """Read a stored rate of 1 or more as a percentage; leave smaller rates alone."""
    if rate >= 1:
        return min(rate / 100, MAX_INTEREST_RATE)
    return rate


def convert_rates(apps, schema_editor):
    settings_model = apps.get_model("demolizzen", "GuildBankSettings")
    for settings in settings_model.objects.filter(interest_rate__gte=1):
        settings.interest_rate = convert_rate(settings.interest_rate)
        settings.save(update_fields=["interest_rate"])


